class Solution:
    def generate(self, numRows: int) -> List[List[int]]:
        # brute-force
        ans = []

        for i in range (1, numRows + 1):
            row = [0] * i
            row[0] = 1
            row[-1] = 1
            for j in range(1, i - 1):
                row[j] = ans[-1][j - 1] + ans[-1][j]
            ans.append(row)
        return ans
